  "targets": {
    "yoga_mat_priya": [
      {"days": "both", "from": 0, "to": 24, "at": "wardrobe_b1", "chance": "usually"},
      {"days": "weekday", "from": 7, "to": 18, "at": "floor_l_l1", "chance": "usually"}
    ],
    "guitar_priya": [
      {"days": "both", "from": 0, "to": 24, "at": "bedroom_floor_b1", "chance": "usually"},
      {"days": "weekday", "from": 14, "to": 17, "at": "floor_l_l1", "chance": "sometimes"}
