    ]
  },
  "claims": [
    {"claim": "The yoga mat is on the living-room floor at midday on a weekday", "target": "yoga_mat_priya", "expect": "floor_l_l1", "days": "weekday", "from": 10, "to": 12},
    {"claim": "The guitar is on the living-room floor during Priya's afternoon practice", "target": "guitar_priya", "expect": "floor_l_l1", "days": "weekday", "from": 15, "to": 16},
    {"claim": "The yoga mat is back in the wardrobe at bedtime", "target": "yoga_mat_priya", "expect": "wardrobe_b1", "days": "both", "from": 22, "to": 24},
